#!/usr/bin/env bash
# Run the differential test (run.jl) for every Julia version, each on its own LLVM, with
# its pinned fixtures, a code_llvm corpus and GPUCompiler modules generated by that Julia.
#
#   test/differential/all.sh WORKDIR [CHANNEL...]
#
# CHANNELs are juliaup channels (default: 1.10 1.11 1.12 1.13 1.14-nightly nightly). Per
# version, WORKDIR/<minor>/ gets the fixtures (julia/), the corpora (corpus/,
# gpucompiler/), the results (out/) and the report (report.txt); WORKDIR/summary.txt has
# the counts of all.
#
# Environment:
#   JULIA_SRC         a local clone of JuliaLang/julia to take the fixtures from (cloned
#                     with --shared); default: a blobless clone from GitHub
#   LLVMEXTRA_BUILDS  a directory with libLLVMExtra builds (llvm<version>-<hash>/lib/),
#                     for as long as JuliaIR needs an unreleased LLVM.jl: the build for
#                     each Julia's LLVM version is set as the libLLVMExtra preference for
#                     its run (and the previous preferences restored afterwards);
#                     LLVMEXTRA_TREE selects among builds of several trees (the <hash>)
#   GPUCOMPILER=0     skip the GPUCompiler corpus
#
# Runs one version at a time. The exit status is non-zero when any version has
# unexplained differences or failed to run.

set -uo pipefail
# Julia's C++ passes abort on some inputs, and GPUCompiler crashes for some targets: no
# core dumps of any of it
ulimit -c 0

ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)
DIFF=$ROOT/test/differential
[ $# -ge 1 ] || { sed -n '2,23p' "${BASH_SOURCE[0]}"; exit 2; }
WORK=$(mkdir -p "$1" && cd "$1" && pwd); shift
CHANNELS=("$@")
[ ${#CHANNELS[@]} -gt 0 ] || CHANNELS=(1.10 1.11 1.12 1.13 1.14-nightly nightly)

# preferences are per environment; restore the user's after the runs
PREFS=("$ROOT/LocalPreferences.toml" "$DIFF/LocalPreferences.toml")
BACKUP=$(mktemp -d)
for p in "${PREFS[@]}"; do [ -f "$p" ] && cp "$p" "$BACKUP/$(echo "$p" | tr / _)"; done
restore() {
    for p in "${PREFS[@]}"; do
        b="$BACKUP/$(echo "$p" | tr / _)"
        if [ -f "$b" ]; then cp "$b" "$p"; else rm -f "$p"; fi
    done
    rm -rf "$BACKUP"
}
trap restore EXIT

jl() { local ch=$1; shift; julia +"$ch" --startup-file=no "$@"; }

status=0
: > "$WORK/summary.txt"
for ch in "${CHANNELS[@]}"; do
    info=$(jl "$ch" -e 'print(VERSION.major, ".", VERSION.minor, " ", Base.libllvm_version, " ", Base.GIT_VERSION_INFO.commit)') ||
        { echo "julia +$ch is not available"; status=1; continue; }
    read -r minor llvm commit <<< "$info"
    dir=$WORK/$minor
    mkdir -p "$dir"
    echo "== Julia $ch ($minor, LLVM $llvm)"

    # the fixtures: the pinned commit, or the nightly build's own
    pin=$(jl "$ch" -e 'using TOML; m = TOML.parsefile(ARGS[1]); p = get(m["pins"], ARGS[2], Dict()); print(get(p, "commit", ""))' \
              "$ROOT/test/upstream/manifest.toml" "$minor")
    [ -n "$pin" ] || pin=$commit
    if [ ! -d "$dir/julia" ]; then
        if [ -n "${JULIA_SRC:-}" ]; then
            git clone -q --shared --no-checkout "$JULIA_SRC" "$dir/julia"
        else
            git clone -q --filter=blob:none --no-checkout https://github.com/JuliaLang/julia "$dir/julia"
        fi
        git -C "$dir/julia" sparse-checkout set --cone test/llvmpasses
    fi
    git -C "$dir/julia" fetch -q origin "$pin" 2>/dev/null
    git -C "$dir/julia" checkout -q "$pin" || { echo "cannot check out $pin"; status=1; continue; }

    # the environment: workspaces from 1.12; before, develop JuliaIR (and LLVM.jl from
    # its [sources]) into a versioned manifest that only this Julia reads
    if [ -n "${LLVMEXTRA_BUILDS:-}" ]; then
        lib=$(ls "$LLVMEXTRA_BUILDS"/llvm"$llvm"-${LLVMEXTRA_TREE:-*}/lib/libLLVMExtra-*.so 2>/dev/null | head -1)
        [ -n "$lib" ] || { echo "no libLLVMExtra for LLVM $llvm in $LLVMEXTRA_BUILDS"; status=1; continue; }
        for p in "${PREFS[@]}"; do printf '[LLVM]\nlibLLVMExtra = "%s"\n' "$lib" > "$p"; done
    fi
    case $minor in
        1.10|1.11)
            touch "$DIFF/Manifest-v$minor.toml"
            jl "$ch" --project="$DIFF" -e '
                using Pkg, TOML
                Pkg.develop(path=ARGS[1])
                src = TOML.parsefile(joinpath(ARGS[1], "Project.toml"))["sources"]["LLVM"]
                Pkg.add(url=src["url"], rev=src["rev"])
                Pkg.instantiate()' "$ROOT" || { status=1; continue; } ;;
        *)
            touch "$ROOT/Manifest-v$minor.toml"
            jl "$ch" --project="$DIFF" -e 'using Pkg; Pkg.resolve(); Pkg.instantiate()' || { status=1; continue; } ;;
    esac

    # the corpora
    rm -rf "$dir/corpus" "$dir/gpucompiler"
    jl "$ch" --project="$DIFF" "$DIFF/corpus.jl" "$dir/corpus" || { status=1; continue; }
    inputs=("$dir/julia/test/llvmpasses" "$dir/corpus" "$DIFF/inputs")
    if [ "${GPUCOMPILER:-1}" != 0 ]; then
        touch "$DIFF/gpucompiler/Manifest-v$minor.toml"
        if jl "$ch" --project="$DIFF/gpucompiler" -e 'using Pkg; Pkg.resolve(); Pkg.instantiate()'; then
            : > "$dir/gpucompiler.log"
            for target in ptx gcn spirv metal native; do
                jl "$ch" --project="$DIFF/gpucompiler" "$DIFF/gpucompiler/corpus.jl" \
                    "$dir/gpucompiler" "$target" >> "$dir/gpucompiler.log" 2>&1 ||
                    echo "GPUCompiler failed for $target on Julia $minor (see $dir/gpucompiler.log)"
            done
            [ -d "$dir/gpucompiler" ] && inputs+=("$dir/gpucompiler")
            # a target that GPUCompiler can't compile for shows here, not as a failure
            gpu=$(for t in ptx gcn spirv metal native; do
                      printf '%s %s, ' "$t" "$(ls "$dir/gpucompiler/$t" 2>/dev/null | wc -l)"
                  done)
            echo "GPUCompiler modules: ${gpu%, }" | tee -a "$WORK/summary.txt"
        else
            echo "no GPUCompiler corpus for Julia $minor"
        fi
    fi

    jl "$ch" --project="$DIFF" "$DIFF/run.jl" --quiet --out "$dir/out" "${inputs[@]}" \
        > "$dir/report.txt" 2>&1 || status=1
    sed -n '/^Julia /,/^`accepted`/p;/^unused exception/p;/^no comparisons/p;/^prefix .* failed on/p;/unexplained difference/p' "$dir/report.txt"
    sed -n '/^Julia /,/^`accepted`/p' "$dir/report.txt" >> "$WORK/summary.txt"
done
exit $status
